<script setup lang="ts">
import { apiPath } from '@/utils/api'
import type { Category } from '@/types/gis';definePageMeta({middleware:'admin',layout:'admin'});const {data}=await useFetch<{items:Category[]}>(apiPath('/api/admin/categories'),{default:()=>({items:[]})});const saving=ref(false);async function save(body:Record<string,unknown>){saving.value=true;try{const out=await $fetch<{id:number}>(apiPath('/api/admin/locations'),{method:'POST',body});await navigateTo(`/admin/locations/${out.id}`)}finally{saving.value=false}}</script><template><div class="space-y-5"><div><h1 class="text-2xl font-bold tracking-tight">Tambah Location</h1><p class="mt-1 text-sm text-muted-foreground">Tambahkan titik GIS secara manual.</p></div><LocationForm :categories="data.items" :submit-label="saving?'Menyimpan...':'Simpan lokasi'" @submit="save" /></div></template>
